def fold_ranges(nums: list[int]) -> str:
    """See SPEC.md."""
    uniq = sorted(set(nums))
    parts: list[str] = []
    i = 0
    n = len(uniq)
    while i < n:
        j = i
        while j + 1 < n and uniq[j + 1] == uniq[j] + 1:
            j += 1
        if j - i + 1 >= 3:
            lo, hi = uniq[i], uniq[j]
            parts.append(f"({lo})-{hi}" if lo < 0 else f"{lo}-{hi}")
        else:
            parts.extend(str(v) for v in uniq[i:j + 1])
        i = j + 1
    return ",".join(parts)

